-- ── hand-written: request context helpers ───────────────────────────────────────────────────────
--
-- Every request-time transaction starts with
--   select set_config('app.user_id', $1, true), set_config('app.tenant_id', $2, true)
-- (src/db/with-tenant.ts). The functions below turn those two settings into facts the policies
-- can trust. The SECURITY DEFINER ones read memberships as the table owner, so a policy on
-- memberships can ask "is this user a member?" without recursing into itself.

CREATE SCHEMA app;
--> statement-breakpoint
REVOKE ALL ON SCHEMA app FROM PUBLIC;
--> statement-breakpoint

CREATE FUNCTION app.current_user_id() RETURNS uuid
  LANGUAGE sql STABLE SET search_path = ''
  AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;
--> statement-breakpoint

-- The tenant this transaction runs in, or null unless the current user is an active member of it.
CREATE FUNCTION app.tenant_id() RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT m.tenant_id
    FROM public.memberships m
    WHERE m.tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid
      AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.active
  $$;
--> statement-breakpoint

-- The current user's role in that tenant, or null.
CREATE FUNCTION app.tenant_role() RETURNS public.member_role
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT m.role
    FROM public.memberships m
    WHERE m.tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid
      AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.active
  $$;
--> statement-breakpoint

-- The current user's branch scope in that tenant: null = every branch, a list = only those.
-- Also null for a non-member, so policies always pair it with tenant_id = app.tenant_id().
CREATE FUNCTION app.tenant_branch_ids() RETURNS uuid[]
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT m.branch_ids
    FROM public.memberships m
    WHERE m.tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid
      AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.active
  $$;
--> statement-breakpoint

-- Every tenant the current user is an active member of (for the tenant switcher).
CREATE FUNCTION app.member_tenant_ids() RETURNS SETOF uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT m.tenant_id
    FROM public.memberships m
    WHERE m.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND m.active
  $$;
--> statement-breakpoint

-- Creates a company and makes the current user its owner. app_runtime has no INSERT on tenants or
-- memberships, so this is the only way the web app can create either.
CREATE FUNCTION app.create_tenant(p_name text, p_email text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_user uuid := app.current_user_id();
  v_tenant uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'app.user_id is not set' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO public.tenants (name, created_by)
    VALUES (btrim(p_name), v_user)
    RETURNING id INTO v_tenant;
  INSERT INTO public.memberships (tenant_id, user_id, email, role, created_by)
    VALUES (v_tenant, v_user, lower(btrim(p_email)), 'owner', v_user);
  RETURN v_tenant;
END $$;
--> statement-breakpoint

-- Functions are executable by PUBLIC unless revoked.
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM PUBLIC;
--> statement-breakpoint

-- ── hand-written: grants for app_runtime ────────────────────────────────────────────────────────

-- These tables were created by this migration, after the default privileges above were changed;
-- the explicit revoke makes the result independent of that ordering.
REVOKE ALL ON public.tenants, public.memberships, public.branches, public.invitations, public.audit_log
  FROM anon, authenticated;
--> statement-breakpoint
GRANT USAGE ON SCHEMA public, app TO app_runtime;
--> statement-breakpoint
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA app TO app_runtime;
--> statement-breakpoint
-- tenants and memberships are read-only to the app: created only through app.create_tenant and by
-- `npm run invites:send`. audit_log is insert-only: no UPDATE or DELETE for anyone but the owner.
GRANT SELECT ON public.tenants, public.memberships TO app_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT ON public.branches, public.invitations, public.audit_log TO app_runtime;
--> statement-breakpoint

