-- A user sees the companies they are an active member of, whichever one is selected.
CREATE POLICY tenants_select ON public.tenants FOR SELECT TO app_runtime
  USING (id IN (SELECT app.member_tenant_ids()));
--> statement-breakpoint

-- A user sees their own memberships; an owner or an auditor sees every membership in the selected
-- company (the auditor needs the names behind the audit log).
CREATE POLICY memberships_select ON public.memberships FOR SELECT TO app_runtime
  USING (
    user_id = (SELECT app.current_user_id())
    OR (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'auditor'))
  );
--> statement-breakpoint

-- Branch scope: a member sees the branches of the selected company that their membership allows.
CREATE POLICY branches_select ON public.branches FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (
      (SELECT app.tenant_branch_ids()) IS NULL
      OR id = ANY ((SELECT app.tenant_branch_ids())::uuid[])
    )
  );
--> statement-breakpoint
CREATE POLICY branches_insert ON public.branches FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint

CREATE POLICY invitations_select ON public.invitations FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) = 'owner');
--> statement-breakpoint
CREATE POLICY invitations_insert ON public.invitations FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
    AND status = 'pending'
    AND sent_at IS NULL
    AND user_id IS NULL
  );
--> statement-breakpoint

-- Any member writes audit rows, but only as themselves, in their real role, in the selected
-- company. Reading the log is for owners and auditors.
CREATE POLICY audit_log_insert ON public.audit_log FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND actor_user_id = (SELECT app.current_user_id())
    AND actor_role = (SELECT app.tenant_role())
  );
--> statement-breakpoint
CREATE POLICY audit_log_select ON public.audit_log FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'auditor'));
